/* Binary search over the sorted code table; 0 when the glyph is absent. */
static const unsigned short *fontcjk_lookup(unsigned int cp)
{
    int lo = 0, hi = FONTCJK_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (fontcjk_code[mid] == cp)
            return fontcjk_rows[mid];
        if (fontcjk_code[mid] < cp)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return 0;
}

